/**
 * slots 控制部分
 */

cc.Class({
    extends: require("LMSlots_Slots_Base"),
    properties: {
        gameUI: {
            default: null,        // The default value will be used only when the component attaching
            type: cc.Node, // optional, default is typeof default
        },

        _roleNode:null,
        _coinSpine:null,
        _coinNode:null,
        // _coinNodeList:[],
    },

    //初始化
    Init:function(row, col){

        this._roleNode = cc.find("zhitianxinchang", this.node)

        this._coinSpine = cc.find("collect/coin_spine", this.node)
        this._coinSpine.active = false
        this._coinNode = cc.find("collect/coin_node", this.node)
        this._topScript = cc.vv.gameData.GetTopScript()
        this._bottomScript = cc.vv.gameData.GetBottomScript()

        // for (let index = 1; index < 4; index++) {
        //     let coinNode = cc.find("collect/coin_" + index, this.node)
        //     coinNode.active = false
        //     this._coinNodeList.push(coinNode)
        // }

        this._cfg = cc.vv.gameData.getGameCfg()
        this._col = col
        this._row = row

        this.createReels(this._col,this._row)

        this._bottomScript.ShowBtnsByState("idle")

        this.RegisterEvent()

        //初始化奖池
        this.CheckJoopLock()
        this.showGameUI(false)
    },

    showGameUI(isShow){
        this.gameUI.active = isShow
        this.node.active = isShow
        // if (isShow) {
        //     for (let index = 0; index < this._coinNodeList.length; index++) {
        //         this._coinNodeList[index].active = false;
        //     }
        //     this._coinNodeList[cc.vv.gameData.getCollectCount()].active = true
        // }
    },

    awaitTime(time){
        return new Promise((sucess, failed)=>{
            this.scheduleOnce(()=>{
                sucess()
            },time);
        });
    },

      //点击旋转按钮调用
    StartMove:function(){
        this._super()
        Global.SlotsSoundMgr.playNormalBgm()
    },

    async OnSpinEnd(){
        //显示中奖路线
        this.ShowWinTrace()
        //显示底部赢钱
        let nWin = cc.vv.gameData.GetGameWin()
        if (cc.vv.gameData.GetTotalFree() > 0 && cc.vv.gameData.GetTotalFree() != cc.vv.gameData.GetFreeTime()) {
            await this.ShowWinCoin(nWin,nWin + this._bottomScript.getCurrentWin(),false)
        }else{
            await this.ShowWinCoin(nWin,nWin,true)
        }
        
        //触发免费
        if(this._gameInfo.select){ 
            if(this._gameInfo.freeResult.isFreeState){  //免费中免费
                
            }else{
                Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.bell)
                await this.awaitTime(2)
                await this.CheckEnterFreeGame();
                this.ShowGameview(true)
                cc.vv.gameData.setIsFreeGame(true);
                await this.awaitTime(1);
            }
        } 
        //触发bonus游戏
        if(this._gameInfo.isBonusGame){
            await this.awaitTime(1.2)
            await this.CheckTriggerSubGame();
        }  
        //触发退出免费
        if(cc.vv.gameData.GetTotalFree() > 0 && cc.vv.gameData.GetFreeTime() == 0){
            await this.CheckExitFreeGame();
            await this.ShowWinCoin(this._bottomScript.getCurrentWin(),this._bottomScript.getCurrentWin(),true)
        }  
        this._topScript.StopMove()
        this._bottomScript.CanDoNextRound()
    },

   
    //showWin
    ShowWinCoin(nAddWin,nTotalWin,bUpdateBalance){
        return new Promise(async (sucess, failed)=>{
            this.ShowBottomWin(nAddWin,nTotalWin,bUpdateBalance,sucess)
        });
    },

    //检查退出免费
    async CheckExitFreeGame(){
        return new Promise(async (sucess, failed)=>{
            cc.vv.gameData.setIsFreeGame(false);
            await this.awaitTime(1)
            await cc.vv.gameData.getPopControl().showFreeGameWinner(this._bottomScript.getCurrentWin())
            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.bonus_complete)
            cc.vv.gameData.getPopControl().showTransitonAnimation()
            await this.awaitTime(1)
            cc.vv.gameData.GetSlotsScript().showGameUI(false)
            cc.vv.gameData.setSlotsIndex(0)
            cc.vv.gameData.GetSlotsScript().showGameUI(true)
            this.ShowGameview(false)
            await this.awaitTime(1);
            Global.SlotsSoundMgr.playNormalBgm(true)
            sucess();
        });
    },

    //检查进入免费
    async CheckEnterFreeGame(){
        return new Promise(async (sucess, failed)=>{
            cc.vv.gameData.GetSlotsScript().node.active = false
            cc.vv.gameData.getSelectControl().enterSelectFeature(sucess)
        });
    },

    //是否触发小游戏
    async CheckTriggerSubGame(){
        return new Promise(async (sucess, failed)=>{
            await this.awaitTime(1)
            if (!cc.vv.gameData.isFreeGame()) {
                this._bottomScript.DoHideWinAction()
            }
            this.showCollectAnimation()
            await this.awaitTime(2.9)
            cc.vv.gameData.setIsBonusGame(true);
            cc.vv.gameData.getBonusControl().enterBonusGame(null,this._gameInfo.jackpotValues, sucess)
        });
    },


      //断线重连的显示
    //可根据自己断线逻辑重写
    async ReconnectShow(){
        this.ShowGameview(cc.vv.gameData.isFreeGame())
        let nTotal = cc.vv.gameData.GetTotalFreeWin()
        this._bottomScript.SetWin(nTotal)
        this._bottomScript.ShowBtnsByState("moveing_1")

        //是否是bonus游戏
        if(cc.vv.gameData.getDeskInfo().allBonusData && cc.vv.gameData.getDeskInfo().allBonusData.isBonusGame){
            await new Promise(async (sucess, failed)=>{
                cc.vv.gameData.setIsBonusGame(true);
                cc.vv.gameData.getBonusControl().enterBonusGame(cc.vv.gameData.getDeskInfo().allBonusData.infoData,cc.vv.gameData.getDeskInfo().allBonusData.jackpotValues, sucess)
            });
            let currentCoin = this._bottomScript.getCurrentWin()
            let bonusWinCoin = cc.vv.gameData.getBonusControl().getBonusWinCoin() 
            await this.ShowWinCoin(bonusWinCoin,currentCoin,true)
        }  
        if (cc.vv.gameData.getDeskInfo().select) {
            await this.CheckEnterFreeGame()
        }

        
        this.CanDoNextRound()
    },

    //显示游戏界面：bFree true显示免费模式的界面，false 普通模式
    ShowGameview:function(bFree){
        if(bFree){
            let total = cc.vv.gameData.GetTotalFree()
            let rest = cc.vv.gameData.GetFreeTime()
        
            //显示免费次数
            this._bottomScript.ShowFreeModel(true,total-rest,total)
            //this.CanDoNextRound()
            
        }
        else{
            this._bottomScript.ShowFreeModel(false)
        }

        //可能还需要显示免费背景图
        let normalBg = cc.find("Canvas/safe_node/spr_bg_normal")
        let normalFree = cc.find("Canvas/safe_node/spr_bg_free")
        if(normalFree){ //存在免费游戏背景才执行下面的逻辑
            if(normalBg){
                normalBg.active = !bFree
            }
            
            normalFree.active = bFree
            
        }
        
    },

    //初始化的时候，检查奖池的锁定状态
    CheckJoopLock:function(){
        let safeNode = this.gameUI
        let curBet = cc.vv.gameData.GetTotalBet()
        let jpNodes = safeNode.getComponentsInChildren('LMSlotMachine_PrizePool')
        for(let i = 0; i < jpNodes.length; i++){
            let item = jpNodes[i]
            item.onEventTotalbetUpdated({detail:curBet})
        }
    },

    async showCollectAnimation(){
        Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.wawa)
        this._roleNode.active = false
        // for (let index = 0; index < this._coinNodeList.length; index++) {
        //     this._coinNodeList[index].active = false;
        // }
        this._roleNode.getComponent(sp.Skeleton).setAnimation(0,"skill02",false)
        await this.awaitTime(4)
        // Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.bowl_open)
        // this._roleNode.getComponent(sp.Skeleton).setAnimation(0,"skill02",false)
        // await this.awaitTime(1)
        // Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.coin_fall)
        // await this.awaitTime(2)
        this._roleNode.active = true
        // this._coinNodeList[0].active = true
        this._roleNode.getComponent(sp.Skeleton).setAnimation(0,"idle",true)
    },

    async showCollectCoinAnimation(node){
        let wordPos = node.convertToWorldSpaceAR(cc.v2(0.0));
        let startPos = this._coinNode.convertToNodeSpaceAR(wordPos)

        let endPos = cc.find("collect/bowl", this.node).convertToWorldSpaceAR(cc.v2(0, 0));
        endPos = this._coinNode.convertToNodeSpaceAR(endPos);
        await this.awaitTime(0.3)
        Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.coin_fly)
        let pianyiPos = [cc.v2(101,56),cc.v2(-95.6,48.6),cc.v2(-47.7,40.2),cc.v2(-44,-124),cc.v2(108.5,28),cc.v2(121.6,-11.6),cc.v2(92.7,-10.7),cc.v2(-135,-49.5)]
        for (let index = 1; index < pianyiPos.length; index++) {
            let pos = cc.v2(startPos.x+ pianyiPos[index].x,startPos.y+ pianyiPos[index].y)
            let newNode = cc.instantiate(this._coinSpine)
            newNode.active = true
            newNode.parent = this._coinNode
            newNode.position = startPos
            newNode.scale = 1
            newNode.angle = Global.random(1,360)
            let coin = cc.find("coin",newNode)
            coin.active = true
            cc.tween(coin).repeatForever(cc.tween(coin).by(0.9,{angle:-50})).start()
            let star = cc.find("star",newNode)
            star.active = false
            cc.tween(newNode).parallel(cc.tween(newNode).delay(0.2).to(0.65,{scale:0.4},{easing:"quadIn"}).call(()=>{
                coin.active = false
                star.active = true
                star.scale = 2.5
                newNode.stopAllActions()
                let starSp = star.getComponent(sp.Skeleton)
                starSp.setAnimation(0,"animation2",false)
                starSp.setCompleteListener(()=>{
                    newNode.parent = null
                    starSp.setCompleteListener(null)
                })
            }),
            cc.tween(newNode).to(0.2,{position:pos},{easing:"quadIn"}).to(0.7,{position:endPos},{easing:"quadIn"})).start()
        }
        if(this._gameInfo){
            let collectCount = this._gameInfo.collectCount;
            if (collectCount > 0) {
                await cc.vv.gameData.awaitTime(1.3);
                if (this._roleNode.getComponent(sp.Skeleton).animation === "idle") {
                    this._roleNode.getComponent(sp.Skeleton).setAnimation(0,"skill01",false);
                    this._roleNode.getComponent(sp.Skeleton).addAnimation(0,"idle",true);
                }


                // let collectCount = cc.vv.gameData.getCollectCount()
                // if (this._gameInfo.collectCount > collectCount) {
                    // let coinNode = this._coinNodeList[this._gameInfo.collectCount]
                    // if(coinNode){
                    //     coinNode.active = true
                    //     coinNode.opacity = 10
                    //     cc.tween(coinNode)
                    //     .delay(1.6)
                    //     .to(1,{opacity:255})
                    //     .start()
                    // }
                // }
            }
            cc.vv.gameData.setCollectCount(collectCount)
        }
    },
});
