/**
 * slot数据管理类
 */
cc.Class({
    extends: require("LMSlots_GameData_Base"),

    properties: {
        _bonusControl:null,
        _popControl:null,  
        _selectControl:null,
        _isFreeGame:false,   
        _isBonusGame:false,
        _slotsArr:[],
        _slotsIndex:0,
        _collectCount:0,
    },

    //注册msg
    RegisterMsg(){
        this._super()
        cc.vv.NetManager.registerMsg(MsgId.SLOT_SUBGAME_DATA,this.onRecvGameAction,this);   
    },
    UnregisterMsg(){
        this._super() 
        cc.vv.NetManager.unregisterMsg(MsgId.SLOT_SUBGAME_DATA,this.onRecvGameAction,false,this);
    },

    onRecvGameAction(msg){
        this._bonusControl.onRecvGameAction(msg)
        this._selectControl.onRecvGameAction(msg)
    },

    //deskInfo进入游戏获得的服务端数据
    init(deskInfo,gameId,gameJackpot){ //已重写
        this._super(deskInfo,gameId,gameJackpot)
        this._isFreeGame = this._deskInfo.restFreeCount > 0
        if (this._isFreeGame) {
            this._slotsIndex = deskInfo.rowIndex - 1
        }else{
            this._slotsIndex = 0
        }
        this._collectCount = this._deskInfo.collectCount
    },

    getCollectCount(){
        if(this._collectCount > 2){
            this._collectCount = 2
        }else if(this._collectCount < 0){
            this._collectCount = 0
        }
        return this._collectCount
    },

    setCollectCount(count){
        this._collectCount = count
    },

    addSlots(cmp){
        this._slotsArr.push(cmp);
    },

    setSlotsIndex(index){
        this._slotsIndex = index
    },

    //获得游戏的slots脚本
    GetSlotsScript:function(){
        return this._slotsArr[this._slotsIndex]
    },

    setBonusControl(cmp){
        this._bonusControl = cmp
    },

    getBonusControl(){
        return this._bonusControl
    },

    setPopControl(cmp){
        this._popControl = cmp
    },

    getPopControl(){
        return this._popControl
    },

    setSelectControl(cmp){
        this._selectControl = cmp
    },

    getSelectControl(){
        return this._selectControl
    },

    setIsFreeGame(isFreeGame){
        this._isFreeGame = isFreeGame
    },

    isFreeGame(){
        return  this._isFreeGame
    },

    setIsBonusGame(isBonus){
        this._isBonusGame = isBonus
    },

    isBonusGame(){
        return  this._isBonusGame
    },

    // update (dt) {},
});
