
//1:mini, 2:minor, 3:major, 4:grand

let fanzhuanAni = ["animation04", "animation03", "animation02", "animation01"]

let towCountAni = ["animation04_1", "animation03_1", "animation02_1", "animation01_1"]

let threeCountAni = ["animation04_2", "animation03_2", "animation02_2", "animation01_2"]

let iconPick = ["theme102_icon_pick_mini", "theme102_icon_pick_minor", "theme102_icon_pick_major", "theme102_icon_pick_grand"]
let textPick = ["theme102_text_pick_mini", "theme102_text_pick_minor", "theme102_text_pick_major", "theme102_text_pick_grand"]
let bgPick = ["theme102_bg_pick_4", "theme102_bg_pick_3", "theme102_bg_pick_2", "theme102_bg_pick_1"]

let coinPosition = [
    cc.v2(-224,-8),cc.v2(-73,-8),cc.v2(73,-8),cc.v2(224,-8),
    cc.v2(-224,-180),cc.v2(-73,-180),cc.v2(73,-180),cc.v2(224,-180),
    cc.v2(-224,-353),cc.v2(-73,-353),cc.v2(73,-353),cc.v2(224,-353),
]
let jackpotNames = ['Mini','Minor','Major','Grand']  //节点名称

cc.Class({
    extends: cc.Component,

    properties: {
        _gameUI:null,
        _coinNode:null,
        _coinAnimationNode:null,
        _mask:null,

        _itemList:[],
        _bonusWinCoin: 0,
        _bonusData:null,
        _pickIndexs:[],

        _lizi:null,
        _prizePool:null,
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad () {
        
    },

    Init() {    
        this._gameUI = cc.find("game_ui", this.node);
        this._gameUI.active = false;
        this._coinNode = cc.find("game_ui/coin_node", this.node);
        this._coinAnimationNode = cc.find("game_ui/coin_node_ani", this.node)
        this._mask = cc.find("game_ui/mask",this.node);
        this._cfg = cc.vv.gameData.getGameCfg()
        for (let index = 1; index < 13; index++) {
                let item = cc.find("item_" + index, this._coinNode)
                item.chooseIndex = index
                this._itemList.push(item);
                Global.btnClickEvent(item, this.onClick, this);
        }
        this._lizi = cc.find("Canvas/safe_node/lizi")
        this._lizi.active = false
        this._prizePool = cc.find("LMSlots_PrizePool_1",this._gameUI)
    },

    //收到子游戏操作
    async onRecvGameAction(msg){
        if(msg.code == 200){
            if(msg.data.rtype == 2){
                let bonusData = msg.data.bonusData
                if (bonusData) {
                    this._pickIndexs.push(this._chooseIndex)
                    this._bonusData[bonusData.type].push(bonusData)
                    await this.clickCoin(bonusData)
                    if (bonusData.isEnd) {
                        this._bonusWinCoin =bonusData.winCoin
                        if(!cc.vv.gameData.isFreeGame()){
                            cc.vv.gameData.AddCoin(this._bonusWinCoin)
                        }
                        this.showEndAnimation()
                        await this.awaitTime(2)
                        this._lizi.active = true
                        await cc.vv.gameData.getPopControl().showBonusGameWinner(this._bonusWinCoin,iconPick[bonusData.type-1],textPick[bonusData.type-1],bgPick[bonusData.type-1])
                        Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.bonus_complete)
                        let currentCoin = cc.vv.gameData.GetSlotsScript()._bottomScript.getCurrentWin()
                        let bonusWinCoin = cc.vv.gameData.getBonusControl().getBonusWinCoin() 
                        await cc.vv.gameData.GetSlotsScript().ShowWinCoin(bonusWinCoin,currentCoin + bonusWinCoin,true)
                        await this.awaitTime(2)
                        cc.vv.gameData.getPopControl().showTransitonAnimation()
                        await this.awaitTime(1)
                        this._lizi.active = false
                        this.exitBonusGame()
                    }
                }
            }
        }
    },

    awaitTime(time){
        return new Promise((sucess, failed)=>{
            this.scheduleOnce(()=>{
                sucess()
            },time);
        });
    },

    //初始化数据
    async initData(data){ 
        this._mask.active = false
        this._bonusWinCoin = 0
        this._bonusData = {[1]:[],[2]:[],[3]:[],[4]:[]}
        this._pickIndexs = []
        this._coinAnimationNode.removeAllChildren()
        this._gameUI.opacity = 80
        cc.tween(this._gameUI)
        .to(1,{opacity:255})
        .start()

        for (let item of this._itemList) {
            item.active = false
            item.getComponent(cc.Button).interactable = false
        }
        if (data) {
            for (let bonusData of data) {
                this._bonusData[bonusData.type].push(bonusData)
                this._pickIndexs.push(bonusData.index)
            } 
            
            for (let index = 0; index < this._itemList.length; index++) {
                let item = this._itemList[index];
                item.active = true
                item.getComponent(cc.Button).interactable = true
                item.position = coinPosition[index]
                item.scale = 1;
                let tongbiNode = item.getChildByName("tongbi");
                tongbiNode.active = true
                tongbiNode.getComponent(sp.Skeleton).setAnimation(0,"animation02",true)
                let roleNode = item.getChildByName("role");
                roleNode.active = false
            }
            for (let i = 1; i < 5; i++) {
                let len = this._bonusData[i].length
                for (let bonusData of this._bonusData[i]) {
                    let item =  this._itemList[bonusData.index-1]
                    item.getComponent(cc.Button).interactable = false
                    let tongbiNode = item.getChildByName("tongbi");
                    tongbiNode.active = false
                    let roleNode = item.getChildByName("role");
                    roleNode.active = true
                    let animation = roleNode.getComponent(sp.Skeleton);
                    if (len > 1) {
                        animation.setAnimation(0,towCountAni[i-1],true)
                    }else{
                        animation.setAnimation(0,fanzhuanAni[i-1],false)
                    }
                } 
            }

        }else{
            await this.awaitTime(1)
            this.showEnterAnimation()
        }
    },
    
    enterBonusGame(data,jackPotVal, exitCallBack){
        Global.SlotsSoundMgr.playBgm(Global.SlotsSoundMgr.bonus_bgm)
        this._exitCallBack = exitCallBack;
        this._gameUI.active = true;
        this.initData(data) 
        for (let i = 0; i < jackPotVal.length; i++) {
            const element = jackPotVal[i];
            let lbl = cc.find("prizePool_"+jackpotNames[i]+"/lbl_num",this._prizePool)
            lbl.getComponent(cc.Label).string = Global.FormatNumToComma(element)
        }
    },

    exitBonusGame(){
        this._gameUI.active = false;
        if (this._exitCallBack) {
            this._exitCallBack(); 
        }
        Global.SlotsSoundMgr.playNormalBgm(true)
    },

    onClick(render){
        render.interactable = false
        let req = {c: MsgId.SLOT_SUBGAME_DATA};
        req.uid = Global.playerData.uid;
        req.gameid = cc.vv.gameData._gameId;
        req.data = {};
        req.data.rtype = 2;
        req.data.index =  render.node.chooseIndex;
        cc.vv.NetManager.send(req);
        this._chooseIndex = render.node.chooseIndex;
    },

    async clickCoin(bonusData){
        return new Promise(async (sucess, failed)=>{
            let tongbiNode = this._itemList[bonusData.index-1].getChildByName("tongbi");
            tongbiNode.active = false
            let roleNode = this._itemList[bonusData.index-1].getChildByName("role");
            roleNode.active = true
            let animation = roleNode.getComponent(sp.Skeleton);
            animation.setAnimation(0,fanzhuanAni[bonusData.type-1],false)

            if (this._bonusData[bonusData.type].length == 1) {
                Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.bonus_coin)
            }
            
            if (this._bonusData[bonusData.type].length == 2) {
                Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.bonus_coin)
                await this.awaitTime(1)
                for (let bonusInfo of this._bonusData[bonusData.type]) {
                    let item = this._itemList[bonusInfo.index-1].getChildByName("role");
                    item.getComponent(sp.Skeleton).setAnimation(0,towCountAni[bonusData.type-1],true)
                }
            }
            if (this._bonusData[bonusData.type].length == 3) {
                Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.bonus_hit)
                await this.awaitTime(1)
                for (let bonusInfo of this._bonusData[bonusData.type]) {
                    let item = this._itemList[bonusInfo.index-1]
                    item.active = false
                    let newNode = cc.instantiate(item)
                    let wordPos = item.convertToWorldSpaceAR(cc.v2(0.0));
                    newNode.active = true
                    newNode.parent = this._coinAnimationNode
                    newNode.position = this._coinAnimationNode.convertToNodeSpaceAR(wordPos)
                    let role = newNode.getChildByName("role");
                    role.getComponent(sp.Skeleton).setAnimation(0,threeCountAni[bonusData.type-1],true)
                }
                this._mask.active = true
                await this.awaitTime(2)  
            }
            sucess()
        });
    },

    showEndAnimation(){
        for (let index = 1; index < 5; index++) {
            if (this._bonusData[index].length < 3) {
                let count = 3-this._bonusData[index].length
                for (let idx = 0; idx < count; idx++) {
                    for (let i = 0; i < 12; i++) {
                        if (!this._pickIndexs.includes(i+1)) {
                            let tongbiNode = this._itemList[i].getChildByName("tongbi");
                            tongbiNode.active = false
                            let roleNode = this._itemList[i].getChildByName("role");
                            roleNode.active = true
                            let animation = roleNode.getComponent(sp.Skeleton);
                            animation.setAnimation(0,fanzhuanAni[index-1],false)
                            this._pickIndexs.push(i+1)
                            break
                        }
                    }
                    
                }
            }            
       }
    },

    showEnterAnimation(){
        return new Promise(async (sucess, failed)=>{
            for (let index = 0; index < this._itemList.length; index++) {
                let item = this._itemList[index];
                item.active = true
                item.getComponent(cc.Button).interactable = false
                item.position = cc.v2(0,880)
                item.scale = 0.2;
                item.runAction(cc.spawn(cc.moveTo(1,coinPosition[index]),cc.rotateBy(1,360),cc.scaleTo(1, 1)))
                let roleNode = item.getChildByName("role");
                roleNode.active = false
                let tongbiNode = item.getChildByName("tongbi");
                tongbiNode.active = true
                tongbiNode.getComponent(sp.Skeleton).setAnimation(0,"animation01",true)
              
            }
            await this.awaitTime(2)
            for (let indx = 0; indx < this._itemList.length; indx++) {
                let item = this._itemList[indx];
                item.getComponent(cc.Button).interactable = true
                let tongbiNode = item.getChildByName("tongbi");
                tongbiNode.active = true
                tongbiNode.getComponent(sp.Skeleton).setAnimation(0,"animation02",true)
            }
            sucess()
        });
    },

    getBonusWinCoin(){
        return this._bonusWinCoin
    },
});
