    async showBonusGameWinner(num, icon,text,bg){
        return new Promise(async (sucess, failed)=>{
            let show_popup = this.node.getChildByName("show_bonus_games_win");
            show_popup.active = true;
            show_popup.opacity = 0
            let atlas = cc.vv.gameData.GetAtlasByName("pick_bs")
            let icon_pick = cc.find("icon_pick",show_popup)
            let text_pick = cc.find("text_pick",show_popup)
            let bg_pick = cc.find("bg_pick",show_popup)
            let startBtn = show_popup.getChildByName("start");
            startBtn.active = false
            icon_pick.getComponent(cc.Sprite).spriteFrame = cc.vv.gameData.GetSpriteFrameByName(icon)
            text_pick.getComponent(cc.Sprite).spriteFrame = cc.vv.gameData.GetSpriteFrameByName(text)
            bg_pick.getComponent(cc.Sprite).spriteFrame = cc.vv.gameData.GetSpriteFrameByName(bg)

            cc.tween(show_popup)
            .to(1.5,{opacity:255})
            .start()

            cc.tween(startBtn)
            .delay(1)
            .call(() => {
                startBtn.active = true
                startBtn.getComponent(cc.Button).interactable = true
            })
            .start()

            await cc.vv.gameData.awaitTime(1);
    
            let coinLable = cc.find("coin", show_popup);
            Global.doRoallNumEff(coinLable,0,num, 2,null,null,0,true);
            startBtn.off("click");
            let func = ()=>{
                startBtn.getComponent(cc.Button).interactable = false
                cc.tween(show_popup)
                    .to(1,{opacity:0})
                    .call(() => {
                        show_popup.active = false
                        sucess();
                    })
                    .start()
            }
            cc.vv.gameData.checkAutoPlay(startBtn, func);
            startBtn.on("click", ()=>{
                startBtn.stopAllActions();
                func();
            });  
        });
    },

    //显示free赢钱
    showFreeGameWinner(num){
        return new Promise(async (sucess, failed)=>{
            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.free_dialog_collect_show)
            this._popup.active = true;
            let show_popup = this._popup.getChildByName("show_free_games_win");
            show_popup.active = true;
            show_popup.setScale(1);
            let lizi = cc.find("fg_jiesuan",show_popup)
            lizi.active = true
            lizi.getComponent(cc.ParticleSystem).resetSystem()
            
            let sp_1 = show_popup.getChildByName("sp_1");
            sp_1.setScale(0.5);
            sp_1.runAction(cc.scaleTo(0.3, 1).easing(cc.easeBackOut()));

            let sp_2 = show_popup.getChildByName("sp_2");
            sp_2.setScale(0);
            sp_2.runAction(cc.scaleTo(0.6, 1).easing(cc.easeBackOut()));

            let startBtn = show_popup.getChildByName("start");
            startBtn.setScale(0);
            startBtn.runAction(cc.scaleTo(0.7, 1).easing(cc.easeBackOut()));

            let showLable = cc.find("lable", show_popup);
            showLable.setScale(0);
            showLable.runAction(cc.scaleTo(0.7, 1).easing(cc.easeBackOut()));

            let coinLable = cc.find("coin", show_popup);
            coinLable.getComponent(cc.Label).string = Global.FormatNumToComma(num);
            startBtn.off("click");
            await this.awaitTime(0.7);
            startBtn.getComponent(cc.Button).interactable = true
            let func = ()=>{
                Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.free_dialog_collect_click)
                startBtn.getComponent(cc.Button).interactable = false
                cc.tween(sp_1).delay(0.4).to(0.3,{scale:0.5},{easing:"backIn"}).start()
                cc.tween(sp_2).to(0.6,{scale:0},{easing:"backIn"}).start()
                cc.tween(startBtn).to(0.7,{scale:0},{easing:"backIn"}).start()
                cc.tween(showLable).to(0.7,{scale:0},{easing:"backIn"}).start()
                cc.tween(show_popup).delay(0.3).to(0.4,{scale:0.3},{easing:"backIn"}).call(()=>{
                    this._popup.active = false;
                    show_popup.active = false;
                    lizi.active = false
                    sucess();
                }).start()
            }
            cc.vv.gameData.checkAutoPlay(startBtn, func);
            startBtn.on("click", ()=>{
                startBtn.stopAllActions();
                func();
            });  
        });
    },
